package mx.uv.dsw.web2;
import java.io.Serializable; import java.sql.SQLException; import java.util.*; import javax.annotation.PostConstruct; import javax.faces.application.FacesMessage; import javax.faces.bean.ManagedBean; import javax.faces.bean.ViewScoped; import javax.faces.context.FacesContext;
@ManagedBean @ViewScoped public class RegistroBean implements Serializable {private String nombre;private List<String> registros=new ArrayList<>();private final RegistroRepository repo=new RegistroRepository();@PostConstruct public void init(){reload();}public String getNombre(){return nombre;}public void setNombre(String n){nombre=n;}public List<String> getRegistros(){return registros;}public void guardar(){try{repo.create(nombre.trim());nombre="";reload();FacesContext.getCurrentInstance().addMessage(null,new FacesMessage("Registro persistido"));}catch(SQLException e){FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_ERROR,"PostgreSQL no disponible",null));}}private void reload(){try{registros=repo.findAll();}catch(SQLException e){registros=new ArrayList<>();}}
}
